+ *     call <sceVdecCoreQueryComputeResourceInfo>
+ *     mov QWORD PTR [rbx+0x10], 0   ; cpuGpuMemory  <- NULL
+ *     mov QWORD PTR [rbx+0x8],  rax ; cpuGpuMemorySize <- computed
