+ *     cmp  QWORD PTR [r14+0x8], required           ; caller's size must be >=
+ *     jb   -> 0x811D0104
+ *     ...
+ *     call <sceVdecCoreInitializeComputeResource>(&{size, mem, pipe, queue})
+ *     mov  QWORD PTR [rbx], handle                 ; *out = queue handle
