+        h[nhits].proc      = proc;
+        h[nhits].hits      = hits;
+        h[nhits].canDecode = (canDecode == 2);
+        snprintf(h[nhits].mods, sizeof h[nhits].mods, "%s", mods);
+
+        h[nhits].name[0] = '?';
+        h[nhits].name[1] = '\0';
+        if (have_comm_off) {
+            uint8_t b[24] = {0};
+
+            if (kernel_copyout(proc + (intptr_t)comm_off, b, sizeof b - 1) == 0) {
+                for (size_t k = 0; k < sizeof b - 1; k++) {
+                    if (b[k] == '\0')
+                        break;
+                    if (b[k] < 0x20 || b[k] >= 0x7f) {
