+                                if (b[k] < 0x20 || b[k] >= 0x7f) {
+                                    b[k] = '\0';
+                                    break;
+                                }
+                            }
+                            if (b[0])
+                                snprintf(nm, sizeof nm, "%s", (char *)b);
+                        }
+                    }
+                    haveCaps = (kernel_get_ucred_caps(pid, caps) == 0);
