+                           dec == 2 ? "   *** CAN DECODE ***" : "");
+                    printf("             modules : %s\n", mods);
+                    printf("             authid  : 0x%016llx%s\n",
+                           (unsigned long long)a,
+                           a == APPSLOT_AUTHID ? "   SAME AS OUR APP SLOT"
+                           : a == DECODER_MODULE_AUTHID
