+    if (visible <= 1) {
+        printf("  *** THE CONTROL FAILED. Only this payload - or nothing - is\n"
+               "  visible, so kernel_dynlib_handle does NOT enumerate other\n"
+               "  processes' modules on this firmware, whatever findings.md\n"
