+
+tail:
+    printf("\n  Nothing here scanned anybody's memory. The follow-up that would\n"
+           "  (diffing a working decoder's objects against ours) is deliberately\n"
+           "  not in this build - it needs its own sign-off.\n");
+
+    printf("\ndone\n");
+    fflush(stdout);
+    if (g_log)
+        fclose(g_log);
